"""Prepare the panel preview: two generated files in ``out/`` (git-ignored), then open ``index.html``.

    python examples/panel-preview/build.py [--react-dir <node_modules>]

* ``out/plugin.classic.js``: ``plugin/desktop/plugin.js`` with its three ``import`` lines turned into reads from the
  preview's module table and ``export default`` into a global. Browsers refuse ES modules from ``file://``; a classic
  script loads. Nothing else in the file changes, so the preview runs the real panel code.
* ``out/react.js``: React 19 from a local ``node_modules`` (Hermes's own install by default: React 19 ships no
  browser build), wrapped in a tiny CommonJS loader. MIT-licensed, Copyright (c) Meta Platforms, Inc. and
  affiliates; the licence is copied beside it as ``out/REACT-LICENSE``. Nothing is downloaded.

Standard library only. Run it again after editing ``plugin/desktop/plugin.js``.
"""
from __future__ import annotations

import argparse
import os
import re
import sys
from pathlib import Path

HERE = Path(__file__).resolve().parent
ROOT = HERE.parent.parent
PLUGIN = ROOT / "plugin" / "desktop" / "plugin.js"
OUT = HERE / "out"

IMPORT = re.compile(r"^import\s*\{([^}]*)\}\s*from\s*'([^']+)'\s*$", re.MULTILINE)
MODULES = ("@hermes/plugin-sdk", "react", "react/jsx-runtime")
REACT_FILES = {
    "react": "react/cjs/react.production.js",
    "react/jsx-runtime": "react/cjs/react-jsx-runtime.production.js",
    "scheduler": "scheduler/cjs/scheduler.production.js",
    "react-dom": "react-dom/cjs/react-dom.production.js",
    "react-dom/client": "react-dom/cjs/react-dom-client.production.js",
}


def classic(source: str) -> str:
    """``desktop/plugin.js`` as a classic script. Raises when the file grew an import or export this does not know."""
    def one(match: re.Match) -> str:
        names, module = match.group(1), match.group(2)
        if module not in MODULES:
            raise SystemExit("plugin.js imports %r, which the preview does not provide" % module)
        bound = ", ".join(re.sub(r"\s+as\s+", ": ", n.strip()) for n in names.split(",") if n.strip())
        return "const { %s } = window.__PREVIEW_MODULES__[%r]" % (bound, module)

    out = IMPORT.sub(one, source)
    out, n = re.subn(r"^export default ", "window.__FOREMAN_PLUGIN__ = ", out, flags=re.MULTILINE)
    if n != 1 or re.search(r"^\s*(import|export)\b", out, re.MULTILINE):
        raise SystemExit("plugin.js has an import or export the preview cannot rewrite")
    return "// Generated by build.py from plugin/desktop/plugin.js; do not edit.\n" + out


def find_react(explicit: str | None) -> Path:
    candidates = [Path(explicit)] if explicit else []
    for env in ("HERMES_AGENT_DIR",):
        if os.environ.get(env):
            candidates.append(Path(os.environ[env]) / "node_modules")
    local = os.environ.get("LOCALAPPDATA")
    if local:
        candidates.append(Path(local) / "hermes" / "hermes-agent" / "node_modules")
    candidates += [Path.home() / ".hermes" / "hermes-agent" / "node_modules", ROOT / "node_modules"]
    for c in candidates:
        if all((c / rel).is_file() for rel in REACT_FILES.values()):
            return c
    raise SystemExit("React 19 not found. Pass --react-dir <a node_modules with react, react-dom and scheduler>.\n"
                     "Looked in: " + ", ".join(str(c) for c in candidates))


def react_bundle(node_modules: Path) -> str:
    parts = ["// Generated by build.py: React from %s (MIT, Copyright (c) Meta Platforms, Inc. and affiliates;"
             " see REACT-LICENSE).\n(function () {\nvar process = { env: { NODE_ENV: 'production' } };\nvar defs = {};"
             % node_modules.as_posix()]
    for name, rel in REACT_FILES.items():
        body = (node_modules / rel).read_text(encoding="utf-8")
        parts.append("defs[%r] = function (module, exports, require) {\n%s\n};" % (name, body))
    parts.append("var cache = {};\nfunction require(name) {\n  if (cache[name]) return cache[name].exports;\n"
                 "  if (!defs[name]) throw new Error('preview: no module ' + name);\n"
                 "  var m = { exports: {} }; cache[name] = m; defs[name](m, m.exports, require); return m.exports;\n}\n"
                 "window.__PREVIEW_MODULES__ = { react: require('react'), 'react/jsx-runtime': require('react/jsx-runtime'),"
                 " 'react-dom/client': require('react-dom/client') };\n})();\n")
    return "\n".join(parts)


def main(argv=None) -> int:
    parser = argparse.ArgumentParser(description=__doc__.split("\n\n")[0])
    parser.add_argument("--react-dir", help="a node_modules folder holding react, react-dom and scheduler (React 19)")
    args = parser.parse_args(argv)
    OUT.mkdir(exist_ok=True)
    (OUT / "plugin.classic.js").write_text(classic(PLUGIN.read_text(encoding="utf-8")), encoding="utf-8", newline="\n")
    node_modules = find_react(args.react_dir)
    (OUT / "react.js").write_text(react_bundle(node_modules), encoding="utf-8", newline="\n")
    licence = node_modules / "react" / "LICENSE"
    if licence.is_file():
        (OUT / "REACT-LICENSE").write_text(licence.read_text(encoding="utf-8"), encoding="utf-8", newline="\n")
    print("Preview ready: open %s" % (HERE / "index.html"))
    return 0


if __name__ == "__main__":
    sys.exit(main())
